```python
import json
from pathlib import Path
from typing import Any

class ConfigLoadError(RuntimeError):
    """Raised when an existing config file cannot be read or parsed."""

def load_optional_config(path: Path) -> dict[str, Any] | None:
    """Return parsed config dict, None if absent, or raise ConfigLoadError on corruption."""
    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise ConfigLoadError(f"cannot read {path}: {exc}") from exc
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ConfigLoadError(f"{path}:{exc.lineno}: invalid JSON: {exc.msg}") from exc
    if not isinstance(data, dict):
        raise ConfigLoadError(f"{path}: expected top-level object")
    return data
